 <!DOCTYPE html>
 <html lang="en">
   <head>
     <meta charset="UTF-8" />
     <meta name="viewport" content="width=device-width, initial-scale=1.0" />
     <title>Cat FAQ</title>
     <style>
       :root {
         color-scheme: light;
         --bg: #f4f7fb;
         --panel: rgba(255, 255, 255, 0.78);
         --panel-strong: #ffffff;
         --text: #18212f;
         --muted: #5d697b;
         --border: rgba(24, 33, 47, 0.1);
         --border-strong: rgba(58, 90, 255, 0.22);
         --accent: #4f46e5;
         --accent-strong: #3730a3;
         --shadow: 0 24px 60px rgba(24, 33, 47, 0.12);
         --radius-xl: 28px;
         --radius-lg: 20px;
         --radius-md: 16px;
       }

       * {
         box-sizing: border-box;
       }

       html {
         scroll-behavior: smooth;
       }

       body {
         margin: 0;
         min-height: 100vh;
         font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
           "Segoe UI", sans-serif;
         background:
           radial-gradient(circle at top left, rgba(79, 70, 229, 0.16), transparent 28%),
           radial-gradient(circle at top right, rgba(14, 165, 233, 0.16), transparent 24%),
           linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
         color: var(--text);
       }

       a {
         color: inherit;
