         color: #fff;
         font-weight: 700;
         text-decoration: none;
         transition: transform 0.2s ease;
         z-index: 10;
       }

       .skip-link:focus {
         transform: translateY(0);
       }

       .page-shell {
         width: min(100%, 78rem);
         margin: 0 auto;
         padding: 2rem 1.25rem 4rem;
       }

       .hero {
         position: relative;
         overflow: hidden;
         padding: clamp(2rem, 6vw, 4rem);
         border: 1px solid var(--border);
         border-radius: var(--radius-xl);
         background:
           linear-gradient(135deg, rgba(255, 255, 255, 0.92), rgba(255, 255, 255, 0.7)),
           rgba(255, 255, 255, 0.7);
         box-shadow: var(--shadow);
         backdrop-filter: blur(18px);
       }

       .hero::after {
         content: "";
         position: absolute;
         inset: auto -5rem -6rem auto;
         width: 16rem;
         height: 16rem;
         border-radius: 50%;
         background: radial-gradient(circle, rgba(79, 70, 229, 0.16), transparent 70%);
         pointer-events: none;
       }

       .eyebrow {
         display: inline-flex;
         align-items: center;
         gap: 0.5rem;
         padding: 0.45rem 0.8rem;
         border: 1px solid rgba(79, 70, 229, 0.14);
         border-radius: 999px;
         background: rgba(79, 70, 229, 0.08);
         color: var(--accent-strong);
         font-size: 0.95rem;
         font-weight: 700;
       }

       .hero h1 {
         margin: 1.1rem 0 0.8rem;
         font-size: clamp(2.4rem, 5vw, 4.4rem);
         line-height: 1.02;
         letter-spacing: -0.04em;
       }

       .hero p {
         max-width: 42rem;
         margin: 0;
         color: var(--muted);
         font-size: clamp(1rem, 1.8vw, 1.15rem);
         line-height: 1.7;
       }

       .faq-section {
         margin-top: 2rem;
       }

       .faq-section > h2 {
         margin: 0 0 1rem;
         font-size: clamp(1.4rem, 2vw, 1.8rem);
         letter-spacing: -0.03em;
       }

       .faq-list {
         display: grid;
         gap: 1rem;
       }

       .example {
         border: 1px solid var(--border);
         border-radius: var(--radius-lg);
         background: var(--panel);
         box-shadow: 0 14px 40px rgba(24, 33, 47, 0.08);
         backdrop-filter: blur(14px);
         overflow: hidden;
       }

       .question-heading {
         margin: 0;
       }

       .question-button {
         display: flex;
         justify-content: space-between;
         align-items: center;
         gap: 1rem;
         width: 100%;
         padding: 1.3rem 1.4rem;
         border: 0;
         background: transparent;
         color: var(--text);
         font: inherit;
         font-size: 1.06rem;
         font-weight: 700;
         text-align: left;
         cursor: pointer;
       }

       .question-button:hover {
         background: rgba(79, 70, 229, 0.04);
       }

       .question-button:focus-visible {
         outline: 3px solid var(--accent);
         outline-offset: -3px;
       }

       .question-button .icon {
         flex: none;
         display: inline-grid;
         place-items: center;
         width: 2rem;
         height: 2rem;
         border-radius: 999px;
         background: rgba(79, 70, 229, 0.1);
         color: var(--accent-strong);
         transition: transform 0.2s ease, background-color 0.2s ease;
       }

       .question-button[aria-expanded="true"] .icon {
         transform: rotate(180deg);
         background: rgba(79, 70, 229, 0.16);
       }

       .details {
         padding: 0 1.4rem 1.35rem;
         color: var(--muted);
         line-height: 1.75;
       }

       .details p {
         margin: 0;
       }

       .details strong {
         color: var(--text);
       }

       @media (max-width: 42rem) {
         .page-shell {
           padding-inline: 1rem;
         }

         .question-button,
         .details {
           padding-inline: 1rem;
         }
       }

       @media (prefers-reduced-motion: reduce) {
         html {
           scroll-behavior: auto;
         }

         *,
         *::before,
         *::after {
           animation-duration: 0.01ms !important;
           animation-iteration-count: 1 !important;
           transition-duration: 0.01ms !important;
         }
       }

       @media (forced-colors: active) {
         :root {
           --panel: Canvas;
           --panel-strong: Canvas;
           --text: CanvasText;
           --muted: CanvasText;
           --border: CanvasText;
           --accent: Highlight;
           --accent-strong: Highlight;
         }

         .hero,
         .example,
         .eyebrow,
         .question-button .icon {
           border: 1px solid CanvasText;
           box-shadow: none;
           background: Canvas;
         }

         .skip-link,
         .question-button:focus-visible {
           outline-color: Highlight;
         }
       }
     </style>
   </head>
   <body>
     <a class="skip-link" href="#main-content">Skip to main content</a>
     <div id="root"></div>
     <script>
       const faqItems = [
         {
           id: "why-cats-purr",
           question: "Why do cats purr?",
           answer:
             "Cats purr for more than happiness. They may purr when they feel relaxed, when they want attention, or even when they are soothing themselves during stress or recovery."
         },
         {
           id: "why-cats-sleep",
           question: "Why do cats sleep so much?",
           answer:
             "Cats are natural hunters built for short bursts of activity, so they conserve energy with long rest periods. Adult cats commonly sleep 12 to 16 hours a day, and kittens or seniors may sleep even more."
         },
         {
           id: "cats-see-dark",
           question: "Can cats see in the dark?",
           answer:
             "Cats cannot see in total darkness, but they do see far better than people in very low light. Their eyes are adapted to gather more light, which helps them move confidently at dawn, dusk, and in dim rooms."
         },
         {
           id: "kneading-behavior",
           question: "Why do cats knead with their paws?",
           answer:
             "Kneading often starts in kittenhood while nursing and can carry into adult life as a comfort behavior. Many cats knead when they feel calm, secure, and attached to a person, blanket, or favorite sleeping spot."
         },
         {
           id: "tail-messages",
           question: "What does a cat's tail tell you?",
           answer:
             "A high tail often signals confidence or a friendly greeting, while a puffed tail can mean fear or overstimulation. Watching the tail together with the ears, eyes, and body posture gives the clearest picture of mood."
         },
         {
           id: "best-home-environment",
           question: "How do you create a great home environment for a cat?",
           answer:
             "Give cats vertical space, scratching surfaces, fresh water, clean litter boxes, quiet hiding places, and daily play. A predictable routine and enrichment like puzzle feeders or window perches can help them feel secure and engaged."
         }
       ];

       const escapeHtml = (value) =>
         value
           .replace(/&/g, "&amp;")
           .replace(/</g, "&lt;")
           .replace(/>/g, "&gt;")
           .replace(/"/g, "&quot;")
           .replace(/'/g, "&#39;");

       const Hero = () => `
         <header class="hero">
           <div class="eyebrow">Cat guide</div>
           <h1>Common cat questions, answered clearly.</h1>
           <p>
             Explore quick answers to popular cat FAQs. Each topic opens on demand so the page
             stays easy to scan, simple to navigate, and friendly for keyboard and assistive
             technology users.
           </p>
         </header>
       `;

       const FAQItem = ({ id, question, answer }) => {
         const buttonId = `${id}-button`;
         const panelId = `${id}-panel`;

         return `
           <div class="example">
             <h3 class="question-heading">
               <button
                 class="question-button"
                 type="button"
                 id="${buttonId}"
                 aria-expanded="true"
                 aria-controls="${panelId}"
               >
                 <span>${escapeHtml(question)}</span>
                 <span class="icon" aria-hidden="true">
                   <svg viewBox="0 0 24 24" width="18" height="18" focusable="false" aria-hidden="true">
                     <path
                       d="M6 9.75 12 15l6-5.25"
                       fill="none"
                       stroke="currentColor"
                       stroke-linecap="round"
                       stroke-linejoin="round"
                       stroke-width="2"
                     />
                   </svg>
                 </span>
               </button>
             </h3>
             <div class="details" id="${panelId}" aria-labelledby="${buttonId}">
               <p>${escapeHtml(answer)}</p>
             </div>
           </div>
         `;
       };

       const FAQList = (items) => `
         <section class="faq-section" aria-labelledby="faq-heading">
           <h2 id="faq-heading">Frequently asked questions</h2>
           <div class="faq-list">
             ${items.map((item) => FAQItem(item)).join("")}
           </div>
         </section>
       `;

       const App = ({ items }) => `
         <div class="page-shell">
           <main id="main-content">
             ${Hero()}
             ${FAQList(items)}
           </main>
         </div>
       `;

       const root = document.getElementById("root");
       root.innerHTML = App({ items: faqItems });

       const setExpanded = (button, expanded) => {
         const panel = document.getElementById(button.getAttribute("aria-controls"));
         button.setAttribute("aria-expanded", String(expanded));
         panel.hidden = !expanded;
       };

       document.querySelectorAll(".question-button").forEach((button) => {
         setExpanded(button, false);

         button.addEventListener("click", () => {
           const isExpanded = button.getAttribute("aria-expanded") === "true";
           setExpanded(button, !isExpanded);
         });

         const panel = document.getElementById(button.getAttribute("aria-controls"));
         panel.addEventListener("keydown", (event) => {
           if (event.key === "Escape" && button.getAttribute("aria-expanded") === "true") {
             setExpanded(button, false);
             button.focus();
           }
         });
       });
     </script>
   </body>
 </html>

